'use strict';

const db = require('../../database');
const batch = require('../../batch');


module.exports = {
	name: 'Set "followercount" on each topic object',
	timestamp: Date.UTC(2025, 3, 15),
	method: async function () {
		const { progress } = this;

		progress.total = await db.sortedSetCard('topics:tid');

		await batch.processSortedSet('topics:tid', async (tids) => {
			const keys = tids.map(tid => `tid:${tid}:followers`);
			const followerCounts = await db.setsCount(keys);

			const bulkSet = [];

			followerCounts.forEach((count, idx) => {
				const tid = tids[idx];
				if (count > 0) {
					bulkSet.push([`topic:${tid}`, {followercount: count}]);
				}
			});

			await db.setObjectBulk(bulkSet);

			progress.incr(tids.length);
		}, {
			batch: 500,
		});
	},
};
'use strict';

const db = require('../../database');
const batch = require('../../batch');
const crypto = require('crypto');


module.exports = {
	name: 'Normalize topic thumbnails, post & user uploads to same format',
	timestamp: Date.UTC(2025, 3, 4),
	method: async function () {
		const { progress } = this;

		const [topicCount, postCount, userCount] = await db.sortedSetsCard(['topics:tid', 'posts:pid', 'users:joindate']);
		progress.total = topicCount + postCount + userCount;

		function normalizePath(path) {
			if (path.startsWith('http')) {
				return path;
			}
			path = path.replace(/\\/g, '/');
			if (!path.startsWith('/')) {
				path = `/${path}`;
			}
			return path;
		}

		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');

		await batch.processSortedSet('topics:tid', async (tids) => {
			const keys = tids.map(tid => `topic:${tid}:thumbs`);

			const topicThumbsData = await db.getSortedSetsMembersWithScores(keys);
			const bulkAdd = [];
			const bulkRemove = [];

			topicThumbsData.forEach((topicThumbs, idx) => {
				const tid = tids[idx];
				if (Array.isArray(topicThumbs)) {
					topicThumbs.forEach((thumb) => {
						const normalizedPath = normalizePath(thumb.value);
						if (normalizedPath !== thumb.value) {
							bulkAdd.push([`topic:${tid}:thumbs`, thumb.score, normalizedPath]);
							bulkRemove.push([`topic:${tid}:thumbs`, thumb.value]);
						}
					});
				}
			});

			await db.sortedSetRemoveBulk(bulkRemove);
			await db.sortedSetAddBulk(bulkAdd);

			progress.incr(tids.length);
		}, {
			batch: 500,
		});

		await batch.processSortedSet('posts:pid', async (pids) => {
			const keys = pids.map(pid => `post:${pid}:uploads`);

			const postUploadData = await db.getSortedSetsMembersWithScores(keys);
			const bulkAdd = [];
			const bulkRemove = [];

			postUploadData.forEach((postUploads, idx) => {
				const pid = pids[idx];
				if (Array.isArray(postUploads)) {
					postUploads.forEach((postUpload) => {
						const normalizedPath = normalizePath(postUpload.value);
						if (normalizedPath !== postUpload.value) {
							bulkAdd.push([`post:${pid}:uploads`, postUpload.score, normalizedPath]);
							bulkAdd.push([`upload:${md5(normalizedPath)}:pids`, postUpload.score, pid]);
							bulkRemove.push([`post:${pid}:uploads`, postUpload.value]);
							bulkRemove.push([`upload:${md5(postUpload.value)}:pids`, pid]);
						}
					});
				}
			});

			await db.sortedSetRemoveBulk(bulkRemove);
			await db.sortedSetAddBulk(bulkAdd);

			progress.incr(pids.length);
		}, {
			batch: 500,
		});

		await batch.processSortedSet('users:joindate', async (uids) => {
			const keys = uids.map(uid => `uid:${uid}:uploads`);

			const userUploadData = await db.getSortedSetsMembersWithScores(keys);
			const bulkAdd = [];
			const bulkRemove = [];
			const promises = [];

			userUploadData.forEach((userUploads, idx) => {
				const uid = uids[idx];
				if (Array.isArray(userUploads)) {
					userUploads.forEach((userUpload) => {
						const normalizedPath = normalizePath(userUpload.value);
						if (normalizedPath !== userUpload.value) {
							bulkAdd.push([`uid:${uid}:uploads`, userUpload.score, normalizedPath]);
							promises.push(db.setObjectField(`upload:${md5(normalizedPath)}`, 'uid', uid));

							bulkRemove.push([`uid:${uid}:uploads`, userUpload.value]);
							promises.push(db.delete(`upload:${md5(userUpload.value)}`));
						}
					});

				}
			});

			await Promise.all(promises);
			await db.sortedSetRemoveBulk(bulkRemove);
			await db.sortedSetAddBulk(bulkAdd);

			progress.incr(uids.length);
		}, {
			batch: 500,
		});
	},
};

};

Messaging.canMessageUser = async (uid, toUid) => {
	if (meta.config.disableChat || uid <= 0) {
		throw new Error('[[error:chat-disabled]]');
	}

	if (parseInt(uid, 10) === parseInt(toUid, 10)) {
		throw new Error('[[error:cant-chat-with-yourself]]');
	}
	const [exists, isTargetPrivileged, canChat, canChatWithPrivileged] = await Promise.all([
		user.exists(toUid),
		user.isPrivileged(toUid),
		privileges.global.can('chat', uid),
		privileges.global.can('chat:privileged', uid),
		checkReputation(uid),
	]);

	if (!exists) {
		throw new Error('[[error:no-user]]');
	}

	if (!canChat && !(canChatWithPrivileged && isTargetPrivileged)) {
		throw new Error('[[error:no-privileges]]');
	}

	const [settings, isAdmin, isModerator, isFollowing, isBlocked] = await Promise.all([
		user.getSettings(toUid),
		user.isAdministrator(uid),
		user.isModeratorOfAnyCategory(uid),
		user.isFollowing(toUid, uid),
		user.blocks.is(uid, toUid),
	]);

	if (isBlocked) {
		throw new Error('[[error:chat-user-blocked]]');
	}
	if (settings.restrictChat && !isAdmin && !isModerator && !isFollowing) {
		throw new Error('[[error:chat-restricted]]');
	}

	await plugins.hooks.fire('static:messaging.canMessageUser', {
		uid: uid,
		toUid: toUid,
	});
};

Messaging.canMessageRoom = async (uid, roomId) => {
	if (meta.config.disableChat || uid <= 0) {
		throw new Error('[[error:chat-disabled]]');
	}

	const [roomData, inRoom, canChat] = await Promise.all([
		Messaging.getRoomData(roomId),
		Messaging.isUserInRoom(uid, roomId),
		privileges.global.can(['chat', 'chat:privileged'], uid),
		checkReputation(uid),
		user.checkMuted(uid),
	]);
	if (!roomData) {
		throw new Error('[[error:no-room]]');
	}

	if (!inRoom) {
		throw new Error('[[error:not-in-room]]');
	}

	if (!canChat.includes(true)) {
		throw new Error('[[error:no-privileges]]');
	}

	await plugins.hooks.fire('static:messaging.canMessageRoom', {
		uid: uid,
		roomId: roomId,
	});
};

async function checkReputation(uid) {
	if (meta.config['reputation:disabled']) {
		return;
	}
	const [reputation, isPrivileged] = await Promise.all([
		user.getUserField(uid, 'reputation'),
		user.isPrivileged(uid),
	]);
	if (!isPrivileged && meta.config['min:rep:chat'] > reputation) {
		throw new Error(`[[error:not-enough-reputation-to-chat, ${meta.config['min:rep:chat']}]]`);
	}
}

Messaging.hasPrivateChat = async (uid, withUid) => {
	if (parseInt(uid, 10) === parseInt(withUid, 10) ||
		parseInt(uid, 10) <= 0 || parseInt(withUid, 10) <= 0) {
		return 0;
	}

	const results = await utils.promiseParallel({
		myRooms: db.getSortedSetRevRange(`uid:${uid}:chat:rooms`, 0, -1),
		theirRooms: db.getSortedSetRevRange(`uid:${withUid}:chat:rooms`, 0, -1),
	});
	const roomIds = results.myRooms.filter(roomId => roomId && results.theirRooms.includes(roomId));

	if (!roomIds.length) {
		return 0;
	}

	let index = 0;
	let roomId = 0;
	while (index < roomIds.length && !roomId) {
		/* eslint-disable no-await-in-loop */
		const count = await Messaging.getUserCountInRoom(roomIds[index]);
		if (count === 2) {
			roomId = roomIds[index];
		} else {
			index += 1;
		}
	}

	return roomId;
};

Messaging.canViewMessage = async (mids, roomId, uid) => {
	let single = false;
	if (!Array.isArray(mids) && (utils.isNumber(mids) || activitypub.helpers.isUri(mids))) {
		mids = [mids];
		single = true;
	}
	const isPublic = parseInt(await db.getObjectField(`chat:room:${roomId}`, 'public'), 10) === 1;
	const [midTimestamps, userTimestamp] = await Promise.all([
		db.sortedSetScores(`chat:room:${roomId}:mids`, mids),
		db.sortedSetScore(`chat:room:${roomId}:uids`, uid),
	]);

	const canView = midTimestamps.map(
		midTimestamp => !!(midTimestamp && userTimestamp && (isPublic || userTimestamp <= midTimestamp))
	);

	return single ? canView.pop() : canView;
};

