'use strict';

const db = require('../../database');
const batch = require('../../batch');


module.exports = {
	name: 'Set "followercount" on each topic object',
	timestamp: Date.UTC(2025, 3, 15),
	method: async function () {
		const { progress } = this;

		progress.total = await db.sortedSetCard('topics:tid');

		await batch.processSortedSet('topics:tid', async (tids) => {
			const keys = tids.map(tid => `tid:${tid}:followers`);
			const followerCounts = await db.setsCount(keys);

			const bulkSet = [];

			followerCounts.forEach((count, idx) => {
				const tid = tids[idx];
				if (count > 0) {
					bulkSet.push([`topic:${tid}`, {followercount: count}]);
				}
			});

			await db.setObjectBulk(bulkSet);

			progress.incr(tids.length);
		}, {
			batch: 500,
		});
	},
};
'use strict';

const db = require('../../database');
const batch = require('../../batch');
const crypto = require('crypto');


module.exports = {
	name: 'Normalize topic thumbnails, post & user uploads to same format',
	timestamp: Date.UTC(2025, 3, 4),
	method: async function () {
		const { progress } = this;

		const [topicCount, postCount, userCount] = await db.sortedSetsCard(['topics:tid', 'posts:pid', 'users:joindate']);
		progress.total = topicCount + postCount + userCount;

		function normalizePath(path) {
			if (path.startsWith('http')) {
				return path;
			}
			path = path.replace(/\\/g, '/');
			if (!path.startsWith('/')) {
				path = `/${path}`;
			}
			return path;
		}

		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');

		await batch.processSortedSet('topics:tid', async (tids) => {
			const keys = tids.map(tid => `topic:${tid}:thumbs`);

			const topicThumbsData = await db.getSortedSetsMembersWithScores(keys);
			const bulkAdd = [];
			const bulkRemove = [];

			topicThumbsData.forEach((topicThumbs, idx) => {
				const tid = tids[idx];
				if (Array.isArray(topicThumbs)) {
					topicThumbs.forEach((thumb) => {
						const normalizedPath = normalizePath(thumb.value);
						if (normalizedPath !== thumb.value) {
							bulkAdd.push([`topic:${tid}:thumbs`, thumb.score, normalizedPath]);
							bulkRemove.push([`topic:${tid}:thumbs`, thumb.value]);
						}
					});
				}
			});

			await db.sortedSetRemoveBulk(bulkRemove);
			await db.sortedSetAddBulk(bulkAdd);

			progress.incr(tids.length);
		}, {
			batch: 500,
		});

		await batch.processSortedSet('posts:pid', async (pids) => {
			const keys = pids.map(pid => `post:${pid}:uploads`);

			const postUploadData = await db.getSortedSetsMembersWithScores(keys);
			const bulkAdd = [];
			const bulkRemove = [];

			postUploadData.forEach((postUploads, idx) => {
				const pid = pids[idx];
				if (Array.isArray(postUploads)) {
					postUploads.forEach((postUpload) => {
						const normalizedPath = normalizePath(postUpload.value);
						if (normalizedPath !== postUpload.value) {
							bulkAdd.push([`post:${pid}:uploads`, postUpload.score, normalizedPath]);
							bulkAdd.push([`upload:${md5(normalizedPath)}:pids`, postUpload.score, pid]);
							bulkRemove.push([`post:${pid}:uploads`, postUpload.value]);
							bulkRemove.push([`upload:${md5(postUpload.value)}:pids`, pid]);
						}
					});
				}
			});

			await db.sortedSetRemoveBulk(bulkRemove);
			await db.sortedSetAddBulk(bulkAdd);

			progress.incr(pids.length);
		}, {
			batch: 500,
		});

		await batch.processSortedSet('users:joindate', async (uids) => {
			const keys = uids.map(uid => `uid:${uid}:uploads`);

			const userUploadData = await db.getSortedSetsMembersWithScores(keys);
			const bulkAdd = [];
			const bulkRemove = [];
			const promises = [];

			userUploadData.forEach((userUploads, idx) => {
				const uid = uids[idx];
				if (Array.isArray(userUploads)) {
					userUploads.forEach((userUpload) => {
						const normalizedPath = normalizePath(userUpload.value);
						if (normalizedPath !== userUpload.value) {
							bulkAdd.push([`uid:${uid}:uploads`, userUpload.score, normalizedPath]);
							promises.push(db.setObjectField(`upload:${md5(normalizedPath)}`, 'uid', uid));

							bulkRemove.push([`uid:${uid}:uploads`, userUpload.value]);
							promises.push(db.delete(`upload:${md5(userUpload.value)}`));
						}
					});

				}
			});

			await Promise.all(promises);
			await db.sortedSetRemoveBulk(bulkRemove);
			await db.sortedSetAddBulk(bulkAdd);

			progress.incr(uids.length);
		}, {
			batch: 500,
		});
	},
};

'use strict';

const util = require('util');

const db = require('./database');
const utils = require('./utils');

const DEFAULT_BATCH_SIZE = 100;

const sleep = util.promisify(setTimeout);

exports.processSortedSet = async function (setKey, process, options) {
	options = options || {};

	if (typeof process !== 'function') {
		throw new Error('[[error:process-not-a-function]]');
	}

	// Progress bar handling (upgrade scripts)
	if (options.progress) {
		options.progress.total = await db.sortedSetCard(setKey);
	}

	options.batch = options.batch || DEFAULT_BATCH_SIZE;
	options.reverse = options.reverse || false;

	// use the fast path if possible
	if (db.processSortedSet && typeof options.doneIf !== 'function' && !utils.isNumber(options.alwaysStartAt)) {
		return await db.processSortedSet(setKey, process, options);
	}

	// custom done condition
	options.doneIf = typeof options.doneIf === 'function' ? options.doneIf : function () {};

	let start = 0;
	let stop = options.batch - 1;

	if (process && process.constructor && process.constructor.name !== 'AsyncFunction') {
		process = util.promisify(process);
	}

	const method = options.reverse ? 'getSortedSetRevRange' : 'getSortedSetRange';
	const isByScore = (options.min && options.min !== '-inf') || (options.max && options.max !== '+inf');
	const byScore = isByScore ? 'ByScore' : '';
	const withScores = options.withScores ? 'WithScores' : '';
	let iteration = 1;
	const getFn = db[`${method}${byScore}${withScores}`];
	while (true) {
		/* eslint-disable no-await-in-loop */
		const ids = await getFn(
			setKey,
			start,
			isByScore ? stop - start + 1 : stop,
			options.reverse ? options.max : options.min,
			options.reverse ? options.min : options.max,
		);

		if (!ids.length || options.doneIf(start, stop, ids)) {
			return;
		}
		if (iteration > 1 && options.interval) {
			await sleep(options.interval);
		}
		await process(ids);
		iteration += 1;
		start += utils.isNumber(options.alwaysStartAt) ? options.alwaysStartAt : options.batch;
		stop = start + options.batch - 1;
	}
};

exports.processArray = async function (array, process, options) {
	options = options || {};

	if (!Array.isArray(array) || !array.length) {
		return;
	}
	if (typeof process !== 'function') {
		throw new Error('[[error:process-not-a-function]]');
	}

	const batch = options.batch || DEFAULT_BATCH_SIZE;
	let start = 0;
	if (process && process.constructor && process.constructor.name !== 'AsyncFunction') {
		process = util.promisify(process);
	}
	let iteration = 1;
	while (true) {
		const currentBatch = array.slice(start, start + batch);

		if (!currentBatch.length) {
			return;
		}
		if (iteration > 1 && options.interval) {
			await sleep(options.interval);
		}
		await process(currentBatch);

		start += batch;
		iteration += 1;
	}
};

require('./promisify')(exports);

'use strict';

const notifications = require('../notifications');
const plugins = require('../plugins');
const activitypub = require('../activitypub');
const db = require('../database');
const utils = require('../utils');

module.exports = function (User) {
	User.follow = async function (uid, followuid) {
		await toggleFollow('follow', uid, followuid);
	};

	User.unfollow = async function (uid, unfollowuid) {
		await toggleFollow('unfollow', uid, unfollowuid);
	};

	async function toggleFollow(type, uid, theiruid) {
		if (parseInt(uid, 10) <= 0 || parseInt(theiruid, 10) <= 0) {
			throw new Error('[[error:invalid-uid]]');
		}

		if (parseInt(uid, 10) === parseInt(theiruid, 10)) {
			throw new Error('[[error:you-cant-follow-yourself]]');
		}
		const [exists, isFollowing] = await Promise.all([
			User.exists(theiruid),
			User.isFollowing(uid, theiruid),
		]);
		if (!exists) {
			throw new Error('[[error:no-user]]');
		}

		await plugins.hooks.fire('filter:user.toggleFollow', {
			type,
			uid,
			theiruid,
			isFollowing,
		});

		if (type === 'follow') {
			if (isFollowing) {
				throw new Error('[[error:already-following]]');
			}
			const now = Date.now();
			await db.sortedSetAddBulk([
				[`following:${uid}`, now, theiruid],
				[`followers:${theiruid}`, now, uid],
			]);
		} else {
			if (!isFollowing) {
				throw new Error('[[error:not-following]]');
			}
			await db.sortedSetRemoveBulk([
				[`following:${uid}`, theiruid],
				[`followers:${theiruid}`, uid],
			]);
		}

		const [followingCount, followingRemoteCount, followerCount, followerRemoteCount] = await db.sortedSetsCard([
			`following:${uid}`, `followingRemote:${uid}`, `followers:${theiruid}`, `followersRemote:${theiruid}`,
		]);
		await Promise.all([
			User.setUserField(uid, 'followingCount', followingCount + followingRemoteCount),
			User.setUserField(theiruid, 'followerCount', followerCount + followerRemoteCount),
		]);
	}

	User.getFollowing = async function (uid, start, stop) {
		return await getFollow(uid, 'following', start, stop);
	};

	User.getFollowers = async function (uid, start, stop) {
		return await getFollow(uid, 'followers', start, stop);
	};

	async function getFollow(uid, type, start, stop) {
		if (parseInt(uid, 10) <= 0) {
			return [];
		}
		const uids = await db.getSortedSetRevRange([
			`${type}:${uid}`,
			`${type}Remote:${uid}`,
		], start, stop);

		const data = await plugins.hooks.fire(`filter:user.${type}`, {
			uids: uids,
			uid: uid,
			start: start,
			stop: stop,
		});
		return await User.getUsers(data.uids, uid);
	}

	User.isFollowing = async function (uid, theirid) {
		const isRemote = activitypub.helpers.isUri(theirid);
		if (parseInt(uid, 10) <= 0 || (!isRemote && (theirid, 10) <= 0)) {
			return false;
		}
		const setPrefix = isRemote ? 'followingRemote' : 'following';
		return await db.isSortedSetMember(`${setPrefix}:${uid}`, theirid);
	};

	User.isFollowPending = async function (uid, target) {
		if (utils.isNumber(target)) {
			return false;
		}

		return await db.isSortedSetMember(`followRequests:uid.${uid}`, target);
	};

	User.onFollow = async function (uid, targetUid) {
		const userData = await User.getUserFields(uid, ['username', 'userslug']);
		const { displayname } = userData;

		const notifObj = await notifications.create({
			type: 'follow',
			bodyShort: `[[notifications:user-started-following-you, ${displayname}]]`,
			nid: `follow:${targetUid}:uid:${uid}`,
			from: uid,
			path: `/user/${userData.userslug}`,
			mergeId: 'notifications:user-started-following-you',
		});
		if (!notifObj) {
			return;
		}
		notifObj.user = userData;
		await notifications.push(notifObj, [targetUid]);
	};
};

'use strict';

const validator = require('validator');
const winston = require('winston');

const db = require('../database');
const user = require('../user');
const meta = require('../meta');
const messaging = require('../messaging');
const notifications = require('../notifications');
const privileges = require('../privileges');
const plugins = require('../plugins');
const utils = require('../utils');

const websockets = require('../socket.io');
const socketHelpers = require('../socket.io/helpers');

const chatsAPI = module.exports;

async function rateLimitExceeded(caller, field) {
	const session = caller.request ? caller.request.session : caller.session; // socket vs req
	const now = Date.now();
	const [isPrivileged, reputation] = await Promise.all([
		user.isPrivileged(caller.uid),
		user.getUserField(caller.uid, 'reputation'),
	]);
	const newbie = !isPrivileged && meta.config.newbieReputationThreshold > reputation;
	const delay = newbie ? meta.config.newbieChatMessageDelay : meta.config.chatMessageDelay;
	session[field] = session[field] || 0;

	if (now - session[field] < delay) {
		return true;
	}

	session[field] = now;
	return false;
}

chatsAPI.list = async (caller, { uid = caller.uid, start, stop, page, perPage } = {}) => {
	if ((!utils.isNumber(start) || !utils.isNumber(stop)) && !utils.isNumber(page)) {
		throw new Error('[[error:invalid-data]]');
	}

	if (!start && !stop && page) {
		winston.warn('[api/chats] Sending `page` and `perPage` to .list() is deprecated in favour of `start` and `stop`. The deprecated parameters will be removed in v4.');
		start = Math.max(0, page - 1) * perPage;
		stop = start + perPage - 1;
	}

	return await messaging.getRecentChats(caller.uid, uid || caller.uid, start, stop);
};

chatsAPI.create = async function (caller, data) {
	if (await rateLimitExceeded(caller, 'lastChatRoomCreateTime')) {
		throw new Error('[[error:too-many-messages]]');
	}
	if (!data) {
		throw new Error('[[error:invalid-data]]');
	}

	const isPublic = data.type === 'public';
	const isAdmin = await user.isAdministrator(caller.uid);
	if (isPublic && !isAdmin) {
		throw new Error('[[error:no-privileges]]');
	}

	if (!data.uids || !Array.isArray(data.uids)) {
		throw new Error(`[[error:wrong-parameter-type, uids, ${typeof data.uids}, Array]]`);
	}

	if (!isPublic && !data.uids.length) {
		throw new Error('[[error:no-users-selected]]');
	}
	if (isPublic && (!Array.isArray(data.groups) || !data.groups.length)) {
		throw new Error('[[error:no-groups-selected]]');
	}

	data.notificationSetting = isPublic ?
		messaging.notificationSettings.ATMENTION :
		messaging.notificationSettings.ALLMESSAGES;

	await Promise.all(data.uids.map(uid => messaging.canMessageUser(caller.uid, uid)));
	const roomId = await messaging.newRoom(caller.uid, data);

	return await messaging.getRoomData(roomId);
};

chatsAPI.getUnread = async (caller) => {
	const count = await messaging.getUnreadCount(caller.uid);
	return { count };
};

chatsAPI.sortPublicRooms = async (caller, { roomIds, scores }) => {
	[roomIds, scores].forEach((arr) => {
		if (!Array.isArray(arr) || !arr.every(value => isFinite(value))) {
			throw new Error('[[error:invalid-data]]');
		}
	});

	const isAdmin = await user.isAdministrator(caller.uid);
	if (!isAdmin) {
		throw new Error('[[error:no-privileges]]');
	}

	await db.sortedSetAdd(`chat:rooms:public:order`, scores, roomIds);
	require('../cache').del(`chat:rooms:public:order:all`);
};

chatsAPI.get = async (caller, { uid, roomId }) => await messaging.loadRoom(caller.uid, { uid, roomId });

chatsAPI.post = async (caller, data) => {
	if (!data || !data.roomId || !caller.uid) {
		throw new Error('[[error:invalid-data]]');
	}

	({ data } = await plugins.hooks.fire('filter:messaging.send', {
		data,
		uid: caller.uid,
	}));

	await messaging.canMessageRoom(caller.uid, data.roomId);
	await messaging.checkContent(data.message);

	if (await rateLimitExceeded(caller, 'lastChatMessageTime')) {
		throw new Error('[[error:too-many-messages]]');
	}

	const message = await messaging.addMessage({
		uid: caller.uid,
		roomId: data.roomId,
		content: data.message,
		toMid: data.toMid,
		timestamp: Date.now(),
		ip: caller.ip,
	});
	messaging.notifyUsersInRoom(caller.uid, data.roomId, message);
	user.updateOnlineUsers(caller.uid);

	return message;
};

chatsAPI.update = async (caller, data) => {
	if (!data || !data.roomId) {
		throw new Error('[[error:invalid-data]]');
	}

	if (data.hasOwnProperty('name')) {
		if (!data.name && data.name !== '') {
			throw new Error('[[error:invalid-data]]');
		}
		await messaging.renameRoom(caller.uid, data.roomId, data.name);
	}
	const [roomData, isAdmin] = await Promise.all([
		messaging.getRoomData(data.roomId),
		user.isAdministrator(caller.uid),
	]);
	if (!roomData) {
		throw new Error('[[error:invalid-data]]');
	}
	if (data.hasOwnProperty('groups')) {
		if (roomData.public && isAdmin) {
			await db.setObjectField(`chat:room:${data.roomId}`, 'groups', JSON.stringify(data.groups));
		}
	}
	if (data.hasOwnProperty('notificationSetting') && isAdmin) {
		await db.setObjectField(`chat:room:${data.roomId}`, 'notificationSetting', data.notificationSetting);
	}
	const loadedRoom = await messaging.loadRoom(caller.uid, {
		roomId: data.roomId,
	});
		messaging.isRoomOwner(caller.uid, data.roomId),
		messaging.isUserInRoom(caller.uid, data.roomId),
		messaging.getUsersInRoomFromSet(
			`chat:room:${data.roomId}:uids:online`, data.roomId, start, stop, true
		),
		user.isAdministrator(caller.uid),
		io.getUidsInRoom(`chat_room_${data.roomId}`),
	]);
	if (!isUserInRoom) {
		throw new Error('[[error:no-privileges]]');
	}
	users.forEach((user) => {
		const isSelf = parseInt(user.uid, 10) === parseInt(caller.uid, 10);
		user.canKick = isOwner && !isSelf;
		user.canToggleOwner = utils.isNumber(user.uid) && (isAdmin || isOwner) && !isSelf;
		user.online = parseInt(user.uid, 10) === parseInt(caller.uid, 10) || onlineUids.includes(String(user.uid));
	});
	return { users };
};

chatsAPI.invite = async (caller, data) => {
	if (!data || !data.roomId || !Array.isArray(data.uids)) {
		throw new Error('[[error:invalid-data]]');
	}
	const roomData = await messaging.getRoomData(data.roomId);
	if (!roomData) {
		throw new Error('[[error:invalid-data]]');
	}
	const userCount = await messaging.getUserCountInRoom(data.roomId);
	const maxUsers = meta.config.maximumUsersInChatRoom;
	if (!roomData.public && maxUsers && userCount >= maxUsers) {
		throw new Error('[[error:cant-add-more-users-to-chat-room]]');
	}

	const uidsExist = await user.exists(data.uids);
	if (!uidsExist.every(Boolean)) {
		throw new Error('[[error:no-user]]');
	}
	await Promise.all(data.uids.map(uid => messaging.canMessageUser(caller.uid, uid)));
	await messaging.addUsersToRoom(caller.uid, data.uids, data.roomId);

	delete data.uids;
	return chatsAPI.users(caller, data);
};

chatsAPI.kick = async (caller, data) => {
	if (!data || !data.roomId) {
		throw new Error('[[error:invalid-data]]');
	}
	const uidsExist = await user.exists(data.uids);
	if (!uidsExist.every(Boolean)) {
		throw new Error('[[error:no-user]]');
	}

	// Additional checks if kicking vs leaving
	if (data.uids.length === 1 && parseInt(data.uids[0], 10) === caller.uid) {
		await messaging.leaveRoom([caller.uid], data.roomId);
		await socketHelpers.removeSocketsFromRoomByUids([caller.uid], data.roomId);
		return [];
	}
	await messaging.removeUsersFromRoom(caller.uid, data.uids, data.roomId);
	await socketHelpers.removeSocketsFromRoomByUids(data.uids, data.roomId);
	delete data.uids;
	return chatsAPI.users(caller, data);
};

